def sec(h2: str, lines: list[str], key: str | None = None) -> dict[str, object]:
    return {"key": key or h2.lower().replace(" ", "_"), "h2": h2, "lines": lines}


def slot(item: dict[str, object], alt: str, caption: str, refs: list[str], roles: list[str], prompt: str) -> dict[str, object]:
    return {
        **item,
        "alt": alt,
        "caption": caption,
        "product": {"code": item["code"], "name": item["name"], "pdp": item["pdp"]},
        "local_reference_images": refs,
        "ref_roles": roles,
        "prompt": prompt,
    }


def manifest_base(rank: int, slug: str, focus_kw: str, prefix: str, caption_occasion: str, flatlay_setting: str, keywords: list[str]) -> dict[str, object]:
    stem = slug.replace("-2026", "")
    return {
        "rank": f"Week3-4 Rank {rank}",
        "slug": slug,
        "primary_kw": focus_kw,
        "output_prefix": prefix,
        "caption_occasion": caption_occasion,
        "caption_year": "2026",
        "flatlay_setting": flatlay_setting,
        "workflow": "Higgsfield CLI nano_banana_pro. People shots require @img1 body_image plus @img2 design. Max 2 concurrent generations total. If queue/generation error occurs, wait 40-50 seconds before retry. No visible screens/devices.",
        "higgsfield_jobs": {},
        "higgsfield": {"model": "nano_banana_pro", "aspect_ratio": "16:9", "resolution": "2k", "count": 1},
        "insert_h2s_json": f"output/{prefix}_insert_h2s.json",
        "product_media_json": f"output/{prefix}_product_media.json",
        "output": {
            "hero": f"output/magnific_generated/{stem}-hero-2026.webp",
            "flatlay": f"output/magnific_generated/{stem}-flatlay-2026.webp",
            "lifestyle": f"output/magnific_generated/{stem}-lifestyle-2026.webp",
        },
        "media_titles": {
            "hero": f"{focus_kw} 2026 Hero",
            "flatlay": f"{focus_kw} 2026 Flatlay",
            "lifestyle": f"{focus_kw} 2026 Lifestyle",
        },
        "schema_keywords": keywords,
        "slots": {},
    }


def faqs(topic: str, use_case: str) -> list[tuple[str, str]]:
    return [
        (f"What should I write for {topic}?", f"Write one sincere line that matches the recipient and occasion. For {use_case}, keep it clear, warm, and easy to copy."),
        (f"Can I use these {topic} lines on WhatsApp?", "Yes. Choose a short line for status, a warmer line for a personal chat, and a longer note for a card or caption."),
        ("How do I make the message personal?", "Add a name, a memory, a blessing, or one detail that only the recipient will understand."),
        ("Should the message be short or emotional?", "Use a short message for quick sharing and an emotional message when the bond is close or the moment is meaningful."),
        ("Can I pair the message with a gift?", "Yes. A small jewellery keepsake can make the message feel more thoughtful when the relationship is close."),
    ]


def write_article(rank: int, prefix: str, title: str, slug: str, meta_desc: str, focus_kw: str, intro: list[str], sections: list[dict[str, object]], faq_list: list[tuple[str, str]], config: dict[str, object], optimize: bool, manifest: dict[str, object]) -> None:
    assert 150 <= len(meta_desc) <= 160, (title, len(meta_desc))
    assert len(title) <= 60, (title, len(title))
    sections_json = f"output/{prefix}_sections.json"
    type3_json = f"output/{prefix}_type3_prompts.json"
    write_json(
        sections_json,
        {
            "meta": {"title": title, "slug": slug, "meta_desc": meta_desc, "focus_kw": focus_kw, "yoast_title": title},
            "intro": intro,
            "sections": sections,
            "faqs": faq_list,
        },
    )
    write_json(
        f"output/publish_configs/week34_rank{rank}.json",
        {
            "rank": f"Week3-4 Rank {rank}",
            "sections_json": sections_json,
            "output_prefix": prefix,
            "carousel_id": config["carousel_id"],
            "occasion_year": config["occasion_year"],
            "carousel_alt_prefix": config["carousel_alt_prefix"],
            "gift_h2": config["gift_h2"],
            "gift_blurb": config["gift_blurb"],
            "conclusion_html": config["conclusion_html"],
            "schema_keywords": config["schema_keywords"],
            "type3_prompts_json": type3_json,
            "products": config["products"],
            "flatlay_insert_h2": config["flatlay_insert_h2"],
            "lifestyle_insert_h2": config["lifestyle_insert_h2"],
            "more_reads_html": config["more_reads_html"],
            "how_to_html": config["how_to_html"],
            "faq_h2": config["faq_h2"],
            "min_lines": 84,
        },
    )
    write_json(type3_json, manifest)
    checklist(prefix, rank, title, focus_kw, optimize)


